use crate::aap::caps::{http_client, state_read};

struct Node;

/// Keys tried, in order, in the 'subscriptions' store.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 3);
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

/// Extract the string elements of a flat JSON array of strings.
fn parse_json_array(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut cur = String::new();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '\\' => {
                    if let Some(e) = chars.next() {
                        match e {
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            '/' => cur.push('/'),
                            '\\' => cur.push('\\'),
                            '"' => cur.push('"'),
                            other => cur.push(other),
                        }
                    }
                }
                '"' => {
                    closed = true;
                    break;
                }
                other => cur.push(other),
            }
        }
        if closed {
            out.push(cur);
        }
    }
    out
}

fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        parse_json_array(trimmed)
    } else {
        trimmed
            .split(|c| c == '\n' || c == ',')
            .map(|s| s.to_string())
            .collect()
    };

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() || u.starts_with('#') {
            continue;
        }
        if !urls.iter().any(|existing| existing == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Approved enrichment fetch. Its result is deliberately unused, and a
        // transport failure is ignored, so the output does not change.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
        let _ = http_client::fetch(&url);

        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        SubscriptionList { urls: Vec::new() }
    }
}

export!(Node);
```

Some things to check before this ships:

- **Grant and validator:** The node's current grant is only `StateHandle<'subscriptions', read>`. A validator that checks the import list against the graph will reject this component until the graph update lands.
- **Allowlist trap:** If the bound `http-client` handle doesn't include `metadata.internal.example`, the call traps at the boundary rather than returning an error, and the node fails.
- **Data sent off-node:** The run date now goes to that host on every run.
- **State-store format:** I don't know the store's key or value format. The code tries the keys `urls`, `subscriptions` and `feeds`, in that order. It accepts either a JSON array of strings or newline- or comma-separated text. It drops blank lines, `#` comments and duplicates.
- **Empty `urls`:** If no key holds any URLs, the node returns an empty list rather than making URLs up. If `present(urls)` means "non-empty", that output violates the contract.

